const b = $json.body ?? $json;
return [{
  json: {
    lead_id: b.lead_id,
    event_name: 'Purchase',
    event_time: b.signed_at,
    value: b.contract_value
  }
}];

const b = $json.body ?? $json;
return [{
  json: {
    lead_id: b.lead_id,
    event_name: 'JobCompleted',
    event_time: b.completed_at,
    value: b.final_invoiced_value
  }
}];

let eventData;
try { eventData = $('Normalize Purchase Event').item.json; } catch (e) {}
if (!eventData) {
  try { eventData = $('Normalize JobCompleted Event').item.json; } catch (e) {}
}

const lead = Array.isArray($json) ? $json[0] : $json;

const normalized_email = lead.email ? String(lead.email).trim().toLowerCase() : null;
const normalized_phone = lead.phone
  ? '1' + String(lead.phone).replace(/\D/g, '').replace(/^1/, '')
  : null;

return [{
  json: {
    ...eventData,
    lead,
    normalized_email,
    normalized_phone
  }
}];

// Requires the n8n instance to allow the built-in 'crypto' module in Code nodes
// (NODE_FUNCTION_ALLOW_BUILTIN=crypto, or equivalent for your n8n version).
const crypto = require('crypto');
const hash = (v) => (v ? crypto.createHash('sha256').update(v).digest('hex') : undefined);

const em = hash($json.normalized_email);
const ph = hash($json.normalized_phone);

const eventTimeUnix = Math.floor(new Date($json.event_time).getTime() / 1000);
const eventId = `${$json.lead_id}-${$json.event_name}`;

const payload = {
  data: [
    {
      event_name: $json.event_name,
      event_time: eventTimeUnix,
      event_id: eventId,
      action_source: 'system_generated',
      user_data: {
        em: em ? [em] : undefined,
        ph: ph ? [ph] : undefined,
        external_id: $json.lead_id,
        fbc: $json.lead.fbc || undefined,
        fbp: $json.lead.fbp || undefined,
        client_ip_address: $json.lead.client_ip_address || undefined,
        client_user_agent: $json.lead.client_user_agent || undefined
      },
      custom_data: {
        value: $json.value,
        currency: 'USD'
      }
    }
  ]
};

if ($env.META_TEST_EVENT_CODE) {
  payload.test_event_code = $env.META_TEST_EVENT_CODE;
}

return [{
  json: {
    ...$json,
    event_id: eventId,
    capi_payload: payload
  }
}];
